CREATE TABLE student_accounts (tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), PRIMARY KEY(tenant_id,student_id), UNIQUE(tenant_id,user_id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE student_invites (token_hash TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, student_id TEXT NOT NULL, expires_at INTEGER NOT NULL, used_at INTEGER, FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE assignments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, class_id TEXT NOT NULL, title TEXT NOT NULL, instructions TEXT NOT NULL, due_at TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0 CHECK(published IN(0,1)), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id));
CREATE TABLE submissions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, assignment_id TEXT NOT NULL, student_id TEXT NOT NULL, content TEXT NOT NULL, submitted_at TEXT NOT NULL, score REAL CHECK(score>=0 AND score<=10), feedback TEXT NOT NULL DEFAULT '', graded_at TEXT, UNIQUE(tenant_id,assignment_id,student_id), FOREIGN KEY(tenant_id,assignment_id) REFERENCES assignments(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE questions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), subject TEXT NOT NULL, prompt TEXT NOT NULL, choices TEXT NOT NULL, answer INTEGER NOT NULL CHECK(answer>=0 AND answer<4), explanation TEXT NOT NULL DEFAULT '', UNIQUE(tenant_id,id));
CREATE TABLE exams (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, class_id TEXT NOT NULL, title TEXT NOT NULL, duration INTEGER NOT NULL CHECK(duration BETWEEN 1 AND 180), opens_at TEXT NOT NULL, closes_at TEXT NOT NULL CHECK(closes_at>opens_at), published INTEGER NOT NULL DEFAULT 0, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id));
CREATE TABLE exam_questions (tenant_id TEXT NOT NULL, exam_id TEXT NOT NULL, position INTEGER NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY(tenant_id,exam_id,position), FOREIGN KEY(tenant_id,exam_id) REFERENCES exams(tenant_id,id));
CREATE TABLE attempts (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, exam_id TEXT NOT NULL, student_id TEXT NOT NULL, started_at TEXT NOT NULL, deadline TEXT NOT NULL, answers TEXT NOT NULL DEFAULT '{}', submitted_at TEXT, score REAL, UNIQUE(tenant_id,exam_id,student_id), FOREIGN KEY(tenant_id,exam_id) REFERENCES exams(tenant_id,id), FOREIGN KEY(tenant_id,student_id) REFERENCES students(tenant_id,id));
CREATE TABLE materials (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, class_id TEXT NOT NULL, title TEXT NOT NULL, object_key TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(tenant_id,class_id) REFERENCES classes(tenant_id,id));
CREATE INDEX assignments_tenant ON assignments(tenant_id,class_id);
CREATE INDEX submissions_assignment ON submissions(tenant_id,assignment_id);
CREATE INDEX attempts_exam ON attempts(tenant_id,exam_id);
CREATE INDEX materials_class ON materials(tenant_id,class_id);
